fn copy(arr: &Vec<i8>) -> Vec<i8> {
    // Pre-allocate a new Vec with the same length as the input
    let mut result = Vec::with_capacity(arr.len());
    
    // Iterate over each element in the input vector and push it into the result
    for &value in arr.iter() {
        result.push(value);
    }
    
    result
}

